mapper.delete:
DELETE FROM ecom_forecast
WHERE forecast_date >= #{date}
  AND listing_id IN #{id}

mapper.select:
SELECT f.listing_id, f.store_id, f.forecast_date, f.qty, f.method, f.generated_time
FROM ecom_forecast f
WHERE f.forecast_date >= #{from} AND f.forecast_date < #{to}
  AND f.listing_id IN #{id}
ORDER BY f.listing_id, f.forecast_date
